document.querySelector('.menu-button')?.addEventListener('click',e=>{const n=document.querySelector('.primary-nav');const open=n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));document.body.classList.toggle('menu-open',open)});const observer='IntersectionObserver'in window?new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');observer.unobserve(e.target)}}),{threshold:.08}):null;document.querySelectorAll('.reveal').forEach(e=>observer?observer.observe(e):e.classList.add('in'));document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{const active=x===button;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))});document.querySelectorAll('[data-clinician]').forEach(row=>{row.hidden=filter!=='all'&&!row.dataset.audiences.split(' ').includes(filter)})}));const allowed=['gclid','gbraid','wbraid','utm_source','utm_medium','utm_campaign','utm_term','utm_content','campaign','adgroup','keyword','matchtype','device'];let attribution={};try{attribution=JSON.parse(sessionStorage.getItem('mftAttribution')||'{}')}catch{}const incoming=new URLSearchParams(location.search);allowed.forEach(key=>{if(incoming.has(key))attribution[key]=incoming.get(key)});if(Object.keys(attribution).length)try{sessionStorage.setItem('mftAttribution',JSON.stringify(attribution))}catch{}document.querySelectorAll('a.track-booking').forEach(link=>{try{const url=new URL(link.href);Object.entries(attribution).forEach(([key,value])=>url.searchParams.set(key,value));url.searchParams.set('landing_page',location.pathname);link.href=url.toString()}catch{}});